// Generates TypeScript types, Ajv standalone validators and Go types from schema/.
//
//   node scripts/generate.ts           write the generated files
//   node scripts/generate.ts --check   fail if the files on disk differ from a fresh generation
//
// The generator understands the subset of JSON Schema that schema/ uses: named $defs (objects,
// string and integer enums, primitive aliases), $ref, const, inline primitive enums and arrays.
// Anything else fails loudly, so a schema change that needs new generator support is noticed.
// Output is a pure function of the schema files (sorted inputs, no timestamps).

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import standaloneCode from 'ajv/dist/standalone/index.js';
import {
  allSchemas,
  createAjv,
  messageSchemas,
  packageRoot,
  sharedSchemas,
  type Schema,
} from './schemas.ts';

interface MessageMeta {
  phase: number;
  channels: string[];
  from: string[];
  to: string[];
  replies?: string[];
}

interface MessageDef {
  type: string;
  name: string; // PascalCase, e.g. SlotRequest
  file: string;
  schema: Schema;
  meta: MessageMeta;
  payloadType: string; // named type of the payload
}

interface NamedDef {
  name: string;
  schema: Schema;
  fileId: string;
}

const root = packageRoot;
const tsOutDir = join(root, 'src', 'generated');
const goOutDir = join(root, 'go');
const HEADER = 'Code generated by packages/protocol/scripts/generate.ts. DO NOT EDIT.';

function fail(msg: string): never {
  throw new Error(`generate: ${msg}`);
}

const sharedFiles = sharedSchemas;
const messageFiles = messageSchemas;
const byId = new Map<string, Schema>(allSchemas.map((s) => [s['$id'] as string, s]));

const envelope =
  byId.get('https://openlive.invalid/protocol/v1/envelope.json') ??
  fail('envelope.json not loaded');
const protocolVersion = envelope['x-openlive'].protocolVersion as { major: number; minor: number };

function pascal(s: string): string {
  return s
    .split(/[._/-]/)
    .filter(Boolean)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join('');
}

// Resolves a $ref relative to the file it appears in. Returns the named def it points to.
function resolveRef(ref: string, fileId: string): NamedDef {
  const url = new URL(ref, fileId);
  const fragment = url.hash;
  url.hash = '';
  const file = byId.get(url.href) ?? fail(`unknown schema file in $ref ${ref} (from ${fileId})`);
  const m =
    /^#\/\$defs\/([A-Za-z0-9]+)$/.exec(fragment) ?? fail(`unsupported $ref fragment ${ref}`);
  const key = m[1] ?? fail(`unsupported $ref fragment ${ref}`);
  const schema = (file['$defs'] as Schema | undefined)?.[key] ?? fail(`missing def ${ref}`);
  return { name: (schema['title'] as string | undefined) ?? key, schema, fileId: url.href };
}

// Named types in output order: shared defs in file order, then message payloads by type.
const namedDefs: NamedDef[] = [];
for (const s of sharedFiles) {
  for (const [key, def] of Object.entries((s['$defs'] ?? {}) as Schema)) {
    if (def['title'] !== key) fail(`${s['$id']}#/$defs/${key}: title must equal the def name`);
    namedDefs.push({ name: key, schema: def, fileId: s['$id'] });
  }
}

const messages: MessageDef[] = messageFiles
  .map(({ file, schema }): MessageDef => {
    const type = schema['properties']?.['type']?.['const'] as string | undefined;
    if (!type) fail(`${file}: properties.type.const missing`);
    if (`messages/${type}.json` !== file) fail(`${file}: file name must be <type>.json`);
    const name = pascal(type);
    if (schema['title'] !== `${name}Message`) fail(`${file}: title must be ${name}Message`);
    const payloadRef = schema['properties']['payload']?.['$ref'] as string | undefined;
    if (!payloadRef) fail(`${file}: payload must be a $ref`);
    const payload = resolveRef(payloadRef, schema['$id']);
    for (const [key, def] of Object.entries((schema['$defs'] ?? {}) as Schema)) {
      if (def['title'] !== key) fail(`${file}#/$defs/${key}: title must equal the def name`);
      namedDefs.push({ name: key, schema: def, fileId: schema['$id'] });
    }
    return {
      type,
      name,
      file,
      schema,
      meta: schema['x-openlive'] as MessageMeta,
      payloadType: payload.name,
    };
  })
  .sort((a, b) => (a.type < b.type ? -1 : a.type > b.type ? 1 : 0));

/** The REST request and response bodies: the object defs of rest.json. */
const restBodies = namedDefs.filter(
  (d) => d.fileId.endsWith('/rest.json') && d.schema['type'] === 'object',
);

{
  const seen = new Set<string>();
  for (const d of namedDefs) {
    if (seen.has(d.name)) fail(`duplicate type name ${d.name}`);
    seen.add(d.name);
  }
  const types = new Set(messages.map((m) => m.type));
  for (const m of messages) {
    for (const r of m.meta.replies ?? [])
      if (!types.has(r)) fail(`${m.file}: reply ${r} is not a message type`);
  }
}

// ---------------------------------------------------------------------------------------------
// TypeScript

function tsType(s: Schema, fileId: string): string {
  if (s['$ref']) return resolveRef(s['$ref'], fileId).name;
  if ('const' in s) return JSON.stringify(s['const']);
  if (s['enum']) return (s['enum'] as unknown[]).map((v) => JSON.stringify(v)).join(' | ');
  switch (s['type']) {
    case 'string':
      return 'string';
    case 'integer':
    case 'number':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'array':
      return `${tsType(s['items'], fileId)}[]`;
    case 'object':
      if (!s['properties']) return 'Record<string, unknown>';
  }
  return fail(`unsupported inline schema in ${fileId}: ${JSON.stringify(s)}`);
}

function tsDoc(desc: string | undefined, indent = ''): string {
  return desc ? `${indent}/** ${desc.replace(/\*\//g, '*\\/')} */\n` : '';
}

function enumMemberNames(def: NamedDef): string[] {
  const values = def.schema['enum'] as (string | number)[];
  const names =
    (def.schema['x-enumNames'] as string[] | undefined) ?? values.map((v) => pascal(String(v)));
  if (names.length !== values.length) fail(`${def.name}: x-enumNames length mismatch`);
  return names;
}

function tsNamed(def: NamedDef): string {
  const s = def.schema;
  let out = tsDoc(s['description']);
  if (s['enum']) {
    const names = enumMemberNames(def);
    const values = s['enum'] as unknown[];
    out += `export const ${def.name} = {\n`;
    names.forEach((n, i) => (out += `  ${n}: ${JSON.stringify(values[i])},\n`));
    out += `} as const;\n`;
    out += tsDoc(s['description']);
    out += `export type ${def.name} = (typeof ${def.name})[keyof typeof ${def.name}];\n`;
    return out;
  }
  if (s['type'] === 'object' && s['properties'] && Object.keys(s['properties']).length === 0) {
    return out + `export type ${def.name} = Record<string, never>;\n`;
  }
  if (s['type'] === 'object' && s['properties']) {
    const required = new Set<string>(s['required'] ?? []);
    out += `export interface ${def.name} {\n`;
    for (const [prop, ps] of Object.entries(s['properties'] as Schema)) {
      out += tsDoc(ps['description'], '  ');
      out += `  ${prop}${required.has(prop) ? '' : '?'}: ${tsType(ps, def.fileId)};\n`;
    }
    out += `}\n`;
    return out;
  }
  return out + `export type ${def.name} = ${tsType(s, def.fileId)};\n`;
}

function union(name: string, doc: string, list: MessageDef[]): string {
  return `/** ${doc} */\nexport type ${name} =\n${list.map((m) => `  | ${m.name}Message`).join('\n')};\n`;
}

function generateTypes(): string {
  let out = `// ${HEADER}\n\n`;
  out += `/** Protocol version implemented by this package. */\n`;
  out += `export const PROTOCOL_VERSION = { major: ${protocolVersion.major}, minor: ${protocolVersion.minor} } as const;\n\n`;
  for (const def of namedDefs) out += tsNamed(def) + '\n';

  out += `/** Every message type name. */\nexport const MessageType = {\n`;
  for (const m of messages) out += `  ${m.name}: ${JSON.stringify(m.type)},\n`;
  out += `} as const;\nexport type MessageType = (typeof MessageType)[keyof typeof MessageType];\n\n`;

  for (const m of messages) {
    out += tsDoc(`${m.schema['description']}`);
    out += `export interface ${m.name}Message {\n  type: ${JSON.stringify(m.type)};\n  id?: MessageId;\n  payload: ${m.payloadType};\n}\n\n`;
  }

  const is = (m: MessageDef, ch: string) => m.meta.channels.includes(ch);
  out += union('Message', 'Any protocol message.', messages) + '\n';
  out +=
    union(
      'RoomServerInbound',
      'Messages the RoomDO accepts from clients.',
      messages.filter((m) => is(m, 'room') && m.meta.to.includes('server')),
    ) + '\n';
  out +=
    union(
      'HubServerInbound',
      'Messages the UserHubDO accepts from clients, including the ones it relays.',
      messages.filter((m) => is(m, 'hub') && !m.meta.from.includes('server')),
    ) + '\n';
  out +=
    union(
      'WebInbound',
      'Messages a web client can receive.',
      messages.filter((m) => m.meta.to.includes('web')),
    ) + '\n';
  out +=
    union(
      'HelperInbound',
      'Messages a helper can receive.',
      messages.filter((m) => m.meta.to.includes('helper')),
    ) + '\n';
  out += `/** The payload type of a message type. */\nexport type PayloadOf<T extends MessageType> = Extract<Message, { type: T }>["payload"];\n\n`;

  out += `export type Endpoint = "web" | "helper" | "server";\nexport type Channel = "room" | "hub" | "space";\n\n`;
  out += `export interface MessageInfo {\n  phase: number;\n  channels: readonly Channel[];\n  from: readonly Endpoint[];\n  to: readonly Endpoint[];\n  replies: readonly MessageType[];\n}\n\n`;
  out += `/** Catalogue metadata: planned phase, channels, senders, receivers and possible replies. */\n`;
  out += `export const MESSAGE_INFO: { readonly [T in MessageType]: MessageInfo } = {\n`;
  for (const m of messages) {
    out += `  ${JSON.stringify(m.type)}: { phase: ${m.meta.phase}, channels: ${JSON.stringify(m.meta.channels)}, from: ${JSON.stringify(m.meta.from)}, to: ${JSON.stringify(m.meta.to)}, replies: ${JSON.stringify(m.meta.replies ?? [])} },\n`;
  }
  out += `};\n\n`;
  out += `/** Names of the REST bodies in rest.json (docs/PROTOCOL.md section 11). */\n`;
  out += `export const REST_BODIES = [\n${restBodies.map((d) => `  ${JSON.stringify(d.name)},\n`).join('')}] as const;\n`;
  return out.replace(/","/g, '", "');
}

// Ajv standalone validators (no eval at runtime, so they run in Workers), one per message type
// plus the envelope. They strip unknown properties: receivers ignore unknown fields (PROTOCOL.md).
function generateValidators(): string {
  const ajv = createAjv('lenient', true);
  const exportsMap: Record<string, string> = { Envelope: envelope['$id'] };
  for (const m of messages) exportsMap[m.name] = m.schema['$id'];
  let code = standaloneCode(ajv, exportsMap).replace(/^"use strict";\s*/, '');
  // Ajv emits CommonJS requires for its runtime helpers even in ESM mode; turn them into imports.
  // A default import of CommonJS is the function in some bundlers (Vite, Vitest) and the whole
  // `module.exports` in others (esbuild in Node mode, as wrangler bundles this "type": "module"
  // package), so take `.default` only when the import is not the function itself.
  const imports: string[] = [];
  code = code.replace(
    /const (\w+) = require\("([^"]+)"\)\.default;/g,
    (_m, v: string, mod: string) => {
      imports.push(
        `import ${v}Module from "${mod.endsWith('.js') ? mod : `${mod}.js`}";\n` +
          `const ${v} = typeof ${v}Module === "function" ? ${v}Module : ${v}Module.default;`,
      );
      return '';
    },
  );
  if (/require\(/.test(code)) fail('unexpected require() left in standalone validator code');
  return `// ${HEADER}\n/* eslint-disable */\n${imports.join('\n')}\n${code}\n`;
}

function generateValidatorTypes(): string {
  let out = `// ${HEADER}\n\nimport type { ValidateFunction } from "ajv";\n\n`;
  out += `export declare const Envelope: ValidateFunction;\n`;
  for (const m of messages) out += `export declare const ${m.name}: ValidateFunction;\n`;
  return out;
}

function generateValidatorIndex(): string {
  let out = `// ${HEADER}\n\nimport type { ValidateFunction } from "ajv";\n`;
  out += `import type { MessageType } from "./types.js";\nimport * as v from "./validators-standalone.js";\n\n`;
  out += `/** Payload-level validators by message type. They remove unknown properties in place. */\n`;
  out += `export const messageValidators: { readonly [T in MessageType]: ValidateFunction } = {\n`;
  for (const m of messages) out += `  ${JSON.stringify(m.type)}: v.${m.name},\n`;
  out += `};\n\nexport const envelopeValidator: ValidateFunction = v.Envelope;\n`;
  return out;
}

// ---------------------------------------------------------------------------------------------
// Go

const GO_INITIALISMS: Record<string, string> = {
  Id: 'ID',
  Ids: 'IDs',
  Url: 'URL',
  Sfu: 'SFU',
  Rtt: 'RTT',
  Fps: 'FPS',
  Mime: 'MIME',
  Os: 'OS',
  Sdp: 'SDP',
  Ice: 'ICE',
  Uri: 'URI',
};

function goName(s: string): string {
  const words = pascal(s).match(/[A-Z][a-z0-9]*|[0-9]+/g) ?? fail(`bad identifier ${s}`);
  return words.map((w) => GO_INITIALISMS[w] ?? w).join('');
}

function goType(s: Schema, fileId: string): string {
  if (s['$ref']) return goName(resolveRef(s['$ref'], fileId).name);
  const t = s['type'] ?? (typeof s['const'] === 'string' ? 'string' : undefined);
  switch (t) {
    case 'string':
      return 'string';
    case 'integer':
      return 'int';
    case 'number':
      return 'float64';
    case 'boolean':
      return 'bool';
    case 'array':
      return `[]${goType(s['items'], fileId)}`;
  }
  return fail(`unsupported inline schema for Go in ${fileId}: ${JSON.stringify(s)}`);
}

function goComment(desc: string | undefined, indent = ''): string {
  return desc ? `${indent}// ${desc}\n` : '';
}

function goNamed(def: NamedDef): string {
  const s = def.schema;
  const name = goName(def.name);
  let out = goComment(s['description'] ? `${name}: ${s['description']}` : undefined);
  if (s['enum']) {
    const base = s['type'] === 'integer' ? 'int' : 'string';
    const values = s['enum'] as (string | number)[];
    out += `type ${name} ${base}\n\nconst (\n`;
    enumMemberNames(def).forEach(
      (n, i) => (out += `\t${name}${goName(n)} ${name} = ${JSON.stringify(values[i])}\n`),
    );
    out += `)\n\n`;
    out += `// ${name}Values lists every ${name} in schema order.\nvar ${name}Values = []${name}{${enumMemberNames(
      def,
    )
      .map((n) => `${name}${goName(n)}`)
      .join(', ')}}\n`;
    return out;
  }
  if (s['type'] === 'object' && s['properties']) {
    const required = new Set<string>(s['required'] ?? []);
    out += `type ${name} struct {\n`;
    for (const [prop, ps] of Object.entries(s['properties'] as Schema)) {
      let t = goType(ps, def.fileId);
      const req = required.has(prop);
      if (!req && !t.startsWith('[]')) t = `*${t}`;
      if (ps['enum'])
        out += `\t// One of ${(ps['enum'] as unknown[]).map((v) => JSON.stringify(v)).join(', ')}.\n`;
      out += goComment(ps['description'], '\t');
      out += `\t${goName(prop)} ${t} \`json:"${prop}${req ? '' : ',omitempty'}"\`\n`;
    }
    out += `}\n`;
    return out;
  }
  if (s['type'] === 'object') return out + `type ${name} = map[string]any\n`;
  return out + `type ${name} = ${goType(s, def.fileId)}\n`;
}

function generateGo(): string {
  let out = `// ${HEADER}\n\npackage protocol\n\n`;
  out += `// CurrentProtocol is the protocol version implemented by this package.\nvar CurrentProtocol = ProtocolVersion{Major: ${protocolVersion.major}, Minor: ${protocolVersion.minor}}\n\n`;
  for (const def of namedDefs) out += goNamed(def) + '\n';

  out += `// MessageType is the envelope's type field.\ntype MessageType string\n\nconst (\n`;
  for (const m of messages)
    out += `\tMessageType${goName(m.name)} MessageType = ${JSON.stringify(m.type)}\n`;
  out += `)\n\n`;

  for (const m of messages) {
    out += `// Type implements Payload.\nfunc (${goName(m.payloadType)}) Type() MessageType { return MessageType${goName(m.name)} }\n\n`;
  }

  out += `// NewPayload returns a pointer to a zero payload for t, or nil if t is unknown.\nfunc NewPayload(t MessageType) Payload {\n\tswitch t {\n`;
  for (const m of messages)
    out += `\tcase MessageType${goName(m.name)}:\n\t\treturn &${goName(m.payloadType)}{}\n`;
  out += `\t}\n\treturn nil\n}\n\n`;

  out += `// Messages holds the catalogue metadata of every message type.\nvar Messages = map[MessageType]MessageInfo{\n`;
  const strs = (a: string[]) => `[]string{${a.map((x) => JSON.stringify(x)).join(', ')}}`;
  for (const m of messages) {
    const replies = (m.meta.replies ?? []).map((r) => `MessageType${goName(pascal(r))}`).join(', ');
    out += `\tMessageType${goName(m.name)}: {Phase: ${m.meta.phase}, Channels: ${strs(m.meta.channels)}, From: ${strs(m.meta.from)}, To: ${strs(m.meta.to)}, Replies: []MessageType{${replies}}},\n`;
  }
  out += `}\n\n`;

  out += `// NewRestBody returns a pointer to a zero REST body (rest.json) by schema name, or nil.\nfunc NewRestBody(name string) any {\n\tswitch name {\n`;
  for (const d of restBodies)
    out += `\tcase ${JSON.stringify(d.name)}:\n\t\treturn &${goName(d.name)}{}\n`;
  out += `\t}\n\treturn nil\n}\n`;
  return out;
}

function gofmt(src: string): string {
  return execFileSync('gofmt', [], { input: src, encoding: 'utf8' });
}

// ---------------------------------------------------------------------------------------------
// Write or check

const outputs = new Map<string, string>([
  [join(tsOutDir, 'types.ts'), generateTypes()],
  [join(tsOutDir, 'validators-standalone.js'), generateValidators()],
  [join(tsOutDir, 'validators-standalone.d.ts'), generateValidatorTypes()],
  [join(tsOutDir, 'validators.ts'), generateValidatorIndex()],
  [join(goOutDir, 'protocol_gen.go'), gofmt(generateGo())],
]);

const stale = existsSync(tsOutDir)
  ? readdirSync(tsOutDir)
      .map((f) => join(tsOutDir, f))
      .filter((p) => !outputs.has(p))
  : [];

if (process.argv.includes('--check')) {
  const problems: string[] = stale.map((p) => `unexpected file ${relative(root, p)}`);
  for (const [path, content] of outputs) {
    if (!existsSync(path)) problems.push(`missing ${relative(root, path)}`);
    else if (readFileSync(path, 'utf8') !== content)
      problems.push(`out of date ${relative(root, path)}`);
  }
  if (problems.length) {
    console.error(
      `Generated files differ from the schema:\n  ${problems.join('\n  ')}\nRun: pnpm generate`,
    );
    process.exit(1);
  }
  console.log(
    `Generated files are up to date (${outputs.size} files, ${messages.length} message types).`,
  );
} else {
  for (const p of stale) rmSync(p);
  for (const [path, content] of outputs) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
  }
  console.log(`Generated ${outputs.size} files for ${messages.length} message types.`);
}
